entries[352498] = { ["name"] = "Gemeinsam besser", ["text"] = "100 Meter Reichweite\nSofort\nWenn Ihr Euch während des Kampfs einem Gruppen- oder Schlachtzugsmitglied auf 3 Meter nähert, werdet Ihr beide inspiriert, was Euer beider Meisterschaft für 1 Min. um 109 erhöht.\n\nSpielercharaktere können nur jeweils von einem solchen Effekt betroffen sein." }
entries[352500] = { ["name"] = "Kevins Schlammling", ["text"] = "100 Meter Reichweite\nSofort\nWenn Ihr Eure Nekrolordklassenfähigkeit aktiviert, wird Kevins Schlammling beschworen und kämpft (20 * 1 ) Sek. lang an Eurer Seite. Seine Angriffe lassen Gegner 6% mehr Schaden durch Euch erleiden und er gewährt Euren Verbündeten regelmäßig einen Absorptionsschild in Höhe von [Max(Zaubermacht, Angriffskraft) * .1 * (1 + Vielseitigkeit)] Schaden." }
entries[352501] = { ["name"] = "Angekündigter Schuss", ["text"] = "Seelenbandefähigkeit\nWenn Ihr kritische Treffer erzielt, wird Eure Bewegungsgeschwindigkeit 5 Sek. lang um 20% erhöht.\n\nKann nur einmal alle 10 Sek. auftreten.\n(10s Abklingzeit)" }
