entries[352503] = { ["name"] = "Verbundene Herzen", ["text"] = "Seelenbandefähigkeit\nWenn Ihr durch 'Hainkräftigung' einen Stapel von 'Umgeleitete Anima' erhaltet, werden bis zu 5 Verbündete in der Nähe um 2% ihrer Gesundheit geheilt, bis zu maximal 2000 Gesundheit. Wenn unter diesen Verbündeten Mitglieder anderer Pakte sind, wird der Effekt von 'Umgeleitete Anima' auf Meisterschaft und maximale Gesundheit für 5 Sek. um 50% erhöht." }
