entries[353263] = { ["name"] = "Gleitscheibe des Kartellmeisters", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Nur die reichsten Kartellführer können sich die Metalle leisten, die für die Herstellung der Gleitscheibe des Kartellmeisters benötigt werden.\"\nBeute von:\nSo'leah\nZone:\nTazavesh, der Verhüllte Markt" }
entries[353264] = { ["name"] = "Gleitscheibe des Treuhänders Xy", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Kartell Xy handelt mit allerlei Währungen, doch keine davon ist ihrem inneren Zirkeln mehr Wert als Loyalität.\"\nQuelle:\n[ZENSIERT]" }
entries[353265] = { ["name"] = "Vandals Gleitscheibe", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ein seltener, speziell angepasster Gleiter, der besonders bei heimlichen Treffen zum Einsatz kommt. Er ist so leise, dass er kaum auszumachen ist, was ihn zu einem beliebten Werkzeug jener macht, die aus den Schatten heraus arbeiten.\"\nVandalen der Manaschmiede\nRuhmstufe:\n8\nOrt:\nSchattenpunkt" }
entries[353266] = { ["name"] = "Tee des Wahnsinnigen Herzogs", ["text"] = "100 Meter Reichweite\nSofort\nSprecht mit Theotar in Sündensturz, um den Tee des Wahnsinnigen Herzogs zu erhalten.\n\nWenn Ihr den Tee des Wahnsinnigen Herzogs trinkt, erhöht das 4 Stunden lang Euer Tempo, Eure Vielseitigkeit, Eure kritische Trefferchance oder Eure Hauptwert.\n\nEs kann immer nur der Effekt eines Tees des Wahnsinnigen Herzogs gleichzeitig aktiv sein." }
