entries[353425] = { ["name"] = "Schicksalskonjunktion", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchicksalsschreiber Roh-Kalo löst eine Schicksalskonjunktion aus, sodass nach einer Verzögerung von 6 Sek. mehrere Energiestrahlen im Kampfbereich hervorbrechen.\n\nDie Strahlen fügen getroffenen Zielen 107829 Schattenschaden zu und erhöhen den durch 'Schicksalskonjunktion' erlittenen Schaden für 1 Min. um 50%." }
entries[353426] = { ["name"] = "Schicksalskonjunktion", ["text"] = "Wirken in 5 sek.\nSchicksalsschreiber Roh-Kalo löst eine Schicksalskonjunktion aus, sodass nach einer Verzögerung von 6 Sek. mehrere Energiestrahlen im Kampfbereich hervorbrechen.\n\nDie Strahlen fügen getroffenen Zielen 107829 Schattenschaden zu und erhöhen den durch 'Schicksalskonjunktion' erlittenen Schaden für 1 Min. um 50%." }
